# page.py - the web page lives inside Python so Vercel always bundles it.
INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>PassGuard - Smart Password Security Analyzer</title>\n<style>\n  :root { --bg:#070b12; --card:#0e1626; --line:#1b3a2f; --text:#d7e3ea; --muted:#8aa0ad;\n          --accent:#00e5c0; --weak:#ff4d5e; --medium:#ffc233; --strong:#2ee59d; }\n  * { box-sizing: border-box; }\n  body { margin:0; background:var(--bg); color:var(--text);\n         font-family: "Segoe UI", Calibri, Arial, sans-serif; line-height:1.5; }\n  .wrap { max-width: 900px; margin: 0 auto; padding: 32px 20px 60px; }\n  h1 { color:var(--accent); margin:0 0 4px; font-size:2rem; }\n  h2 { color:var(--accent); font-size:1.15rem; margin:28px 0 10px; }\n  .sub { color:var(--muted); margin:0 0 24px; }\n  .card { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:16px; }\n  .row { display:flex; gap:8px; }\n  input { flex:1; background:#0b1220; border:1px solid var(--accent); color:#fff; font-size:18px;\n          padding:12px 14px; border-radius:10px; letter-spacing:1px; min-width:0; }\n  button { background:transparent; color:var(--accent); border:1px solid var(--accent);\n           border-radius:10px; padding:0 16px; cursor:pointer; font-size:14px; }\n  button:hover { background:rgba(0,229,192,.1); }\n  .meter { height:14px; background:#16202e; border-radius:8px; overflow:hidden; margin:14px 0 6px; }\n  .fill { height:100%; width:0; background:var(--weak); transition: width .3s, background .3s; }\n  .label { font-weight:700; font-size:1.2rem; }\n  .grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(170px,1fr)); gap:12px; }\n  .metric small { color:var(--muted); display:block; }\n  .metric b { font-size:1.3rem; }\n  .ok { color:var(--strong); } .bad { color:var(--weak); }\n  ul { margin:0; padding-left:20px; }\n  li { margin:6px 0; }\n  .issue { background:rgba(255,77,94,.1); border:1px solid rgba(255,77,94,.4); border-radius:8px;\n           padding:8px 12px; margin:6px 0; list-style:none; }\n  table { width:100%; border-collapse:collapse; font-size:.95rem; }\n  th, td { text-align:left; padding:8px 10px; border-bottom:1px solid var(--line); }\n  th { color:var(--accent); }\n  .scroll { overflow-x:auto; }\n  .hidden { display:none; }\n  .msg { color:var(--muted); padding:16px 0; }\n  .err { color:var(--weak); }\n</style>\n</head>\n<body>\n<div class="wrap">\n  <h1>🛡️ PassGuard</h1>\n  <p class="sub">Smart Password Security Analyzer. Passwords are analyzed in memory only and never stored or logged.</p>\n\n  <div class="card">\n    <div class="row">\n      <input id="pw" type="password" placeholder="Type a password to analyze..." autocomplete="off">\n      <button id="toggle" type="button">Show</button>\n    </div>\n    <div class="meter"><div class="fill" id="fill"></div></div>\n    <div><span class="label" id="label">Waiting...</span> <span id="score" class="sub"></span></div>\n  </div>\n\n  <div id="msg" class="msg">Start typing: the live report appears here.</div>\n\n  <div id="results" class="hidden">\n    <h2>📊 Security Dashboard</h2>\n    <div class="grid">\n      <div class="card metric"><small>Length</small><b id="m-len"></b></div>\n      <div class="card metric"><small>Entropy</small><b id="m-ent"></b></div>\n      <div class="card metric"><small>Crack time</small><b id="m-crack"></b></div>\n      <div class="card metric"><small>Score</small><b id="m-score"></b></div>\n    </div>\n\n    <h2>🔤 Character Types</h2>\n    <div class="grid" id="types"></div>\n\n    <h2>⚠️ Weak Patterns</h2>\n    <ul id="issues"></ul>\n\n    <h2>💡 Suggestions</h2>\n    <div class="card"><ul id="suggestions"></ul></div>\n\n    <h2>📝 Final Security Report</h2>\n    <div class="card scroll">\n      <table>\n        <thead><tr><th>Parameter</th><th>Value</th><th>Status</th></tr></thead>\n        <tbody id="report"></tbody>\n      </table>\n    </div>\n  </div>\n</div>\n\n<script>\n  const $ = (id) => document.getElementById(id);\n  const colors = { Weak: "var(--weak)", Medium: "var(--medium)", Strong: "var(--strong)" };\n  let timer = null;\n\n  function esc(s) {\n    const d = document.createElement("div");\n    d.textContent = String(s);\n    return d.innerHTML;\n  }\n\n  $("toggle").addEventListener("click", () => {\n    const hidden = $("pw").type === "password";\n    $("pw").type = hidden ? "text" : "password";\n    $("toggle").textContent = hidden ? "Hide" : "Show";\n  });\n\n  $("pw").addEventListener("input", () => {\n    clearTimeout(timer);\n    timer = setTimeout(analyze, 250);   // debounce so we don\'t call on every keystroke\n  });\n\n  function reset(text, isError) {\n    $("results").classList.add("hidden");\n    $("fill").style.width = "0";\n    $("label").textContent = "Waiting...";\n    $("score").textContent = "";\n    $("msg").className = "msg" + (isError ? " err" : "");\n    $("msg").textContent = text;\n    $("msg").classList.remove("hidden");\n  }\n\n  async function analyze() {\n    const password = $("pw").value;\n    if (!password) { reset("Start typing: the live report appears here."); return; }\n\n    try {\n      const res = await fetch("/analyze", {\n        method: "POST",\n        headers: { "Content-Type": "application/json" },\n        body: JSON.stringify({ password })\n      });\n      const data = await res.json();\n      if (!res.ok) { reset(data.error || "Something went wrong.", true); return; }\n      render(data);\n    } catch (e) {\n      reset("Could not reach the server. Please try again.", true);\n    }\n  }\n\n  function render(r) {\n    $("msg").classList.add("hidden");\n    $("results").classList.remove("hidden");\n\n    const color = colors[r.strength_label] || colors.Weak;\n    $("fill").style.width = r.score + "%";\n    $("fill").style.background = color;\n    $("label").textContent = r.strength_label;\n    $("label").style.color = color;\n    $("score").textContent = r.score + " / 100";\n\n    $("m-len").textContent = r.length;\n    $("m-ent").textContent = Math.round(r.entropy * 10) / 10 + " bits";\n    $("m-crack").textContent = r.crack_time;\n    $("m-score").textContent = r.score;\n\n    const names = { uppercase: "Uppercase (A-Z)", lowercase: "Lowercase (a-z)",\n                    numbers: "Numbers (0-9)", special: "Special (!@#)" };\n    $("types").innerHTML = Object.keys(names).map(k =>\n      `<div class="card metric"><small>${names[k]}</small>\n       <b class="${r.character_types[k] ? "ok" : "bad"}">${r.character_types[k] ? "✅ Yes" : "❌ No"}</b></div>`\n    ).join("");\n\n    $("issues").innerHTML = r.pattern_issues.length\n      ? r.pattern_issues.map(p => `<li class="issue">${esc(p[0])}</li>`).join("")\n      : `<li class="ok">✅ No weak patterns found.</li>`;\n\n    $("suggestions").innerHTML = r.suggestions.map(s => `<li>${esc(s)}</li>`).join("");\n\n    $("report").innerHTML = r.report.map(row =>\n      `<tr><td>${esc(row.Parameter)}</td><td>${esc(row.Value)}</td><td>${esc(row.Status)}</td></tr>`\n    ).join("");\n  }\n</script>\n</body>\n</html>\n'
